import csv, re, pathlib
from datetime import date, datetime, timedelta

root = pathlib.Path('/app/logs')
current = date(2025, 8, 12)
windows = {
    'today': (current, current),
    'last_7_days': (current - timedelta(days=6), current),
    'last_30_days': (current - timedelta(days=29), current),
    'month_to_date': (date(2025, 8, 1), current),
}
severities = ['ERROR','WARNING','INFO']
counts = {period: {sev: 0 for sev in severities} for period in list(windows) + ['total']}

for path in sorted(root.glob('*.log')):
    m = re.match(r'^(\d{4}-\d{2}-\d{2})_.+\.log$', path.name)
    if not m:
        continue
    fdate = datetime.strptime(m.group(1), '%Y-%m-%d').date()
    line = path.read_text(errors='replace').splitlines()
    for ln in line:
        sev = None
        if '[ERROR]' in ln:
            sev = 'ERROR'
        elif '[WARNING]' in ln:
            sev = 'WARNING'
        elif '[INFO]' in ln:
            sev = 'INFO'
        if sev is None:
            continue
        counts['total'][sev] += 1
        for period, (start, end) in windows.items():
            if start <= fdate <= end:
                counts[period][sev] += 1

out = pathlib.Path('/app/summary.csv')
rows = [('period','severity','count')]
order = ['today','last_7_days','last_30_days','month_to_date','total']
for period in order:
    for sev in severities:
        rows.append((period, sev, str(counts[period][sev])))
with out.open('w', newline='') as f:
    w = csv.writer(f)
    w.writerows(rows)

print(counts)
print('wrote', out)
